    def __init__(self, count: int, n: int, is_sub_class: bool) -> None:
        self.count = count
        self.n = n
        self.some = None
        if n > 1 and not is_sub_class:
            self.some = A(self.count + 1, self.n - 1, is_sub_class)

    def mystery_method(self) -> int:
        if self.some is not None:
            return self.n + self.some.mystery_method()
        return self.n

class B(A):
    def __init__(self, n: int) -> None:
        A.__init__(self, 0, n, True)

    def mystery_method(self) -> int:
