class SimpleListMap:
    def __init__(self):
        # 使用 list 存储 (key, value)
        self._items = []

    def put(self, key, value):
        # 若存在相同 key，则更新，否则追加
        for i, (k, v) in enumerate(self._items):
            if k == key:
                self._items[i] = (key, value)
                return
        self._items.append((key, value))

    def get(self, key, default=None):
        for k, v in self._items:
            if k == key:
                return v
        return default

