# 从后缀表达式构造表达式树
def build_expr_tree_from_postfix(tokens):
    stack = []
    for tok in tokens:
        if tok in '+-*/':
            # 操作符，弹出两个操作数作为子树
            right = stack.pop()
            left = stack.pop()
            node = ExprNode(tok, left, right)
            stack.append(node)
        else:
            # 操作数
            stack.append(ExprNode(int(tok)))
    return stack[-1]

# 递归求值（后序遍历）
def eval_tree(node):
    if node.is_leaf():
        return node.value
    left_val = eval_tree(node.left)
    right_val = eval_tree(node.right)
    if node.value == '+':
        return left_val + right_val
    if node.value == '-':
        return left_val - right_val
    if node.value == '*':
        return left_val * right_val
    if node.value == '/':
        return left_val / right_val

